function portPrompt(p, base) {
  return `${COMMON}
TASK (M3-R3 port, key ${p.key}; your base commit is ${base}: your work so far is git diff ${base} in ${REPO}): ${p.scope}${RESUME[p.key] ? '\n' + RESUME[p.key].note : ''}
DONE WHEN: ${p.done}.
Read ${ANSWERS} first and again before you write your report (a later answer there overrides this task's text; quote what it changed).
Report: ${REPO}/docs/m3-r3-${p.key}.md (what changed and why, file by file; each Cataclysm behaviour with its exe function and address; each HWI-FEATURE with its surfaces (the cfg row, the switch, the console row, the settings-line row, the key, the control) and its default; the build results; the plain-harness runs with label, milestone and first stop; the new or extended self-tests, switches, tools and harness flags; the fence's numbers; the delta-map review entries you added; the CAT-TODOs you closed or re-targeted; every stream and dump before and after with the fields and first tick that moved and the reason; THE USER'S CHECK for the play-test brief (the tools/play.sh command, the mission and moment, where to look, what to report); a "For STATE.md" list of chosen names and defaults; what is left and its owner). Subsystems: split your scope into 3-6 subsystems and record them in the done marker.
Return via StructuredOutput: report, files_changed, summary, done_when_met, harness_milestone, first_stop, stream_hash_after (the sha256 prefix of your final headless Mission01 mission run's run.hwo; its content is judged by hwo_compare), counts, open_questions (questions for the user prefixed "USER:"), and missions_passed (the mission numbers whose self-test passed, if you ran them).`
}

function auditPrompt(p, r, base) {
  return `${COMMON}
TASK: ADVERSARIAL AUDITOR for M3-R3 port "${p.key}" (producer result: ${JSON.stringify(r || {}).slice(0, 2500)}). RESUME RULE: if ${REPO}/docs/audits/m3-r3-${p.key}.md exists and ends with a "Verdict:" line, return its numbers immediately.
1. Build from clean in a separate dir: rm -rf ${SCRATCH}/build-audit-m3r3-${p.key} && meson setup / compile the debug and release configurations there exactly as tools/build.sh does (read it), 0 warnings under -Werror; record sizes. Also the Windows cross build's sources: tools/release_win64.sh (or its meson cross setup, read it) must still configure and compile (0 warnings) when the port added a source file or a GL call.
2. ${p.audit}
3. Read the full diff of this port: git diff ${base} in ${REPO} (the commits after ${base}, WIP snapshots included, plus the working tree; commits whose subjects show they are the user's or the orchestrator's, such as harness rules, asset tools, oracle sessions, the play-test launcher, STATE.md edits, cycle/answers, merges or workflow scripts and relaunches, and the separate "M3 Windows build" stream, are not port work). Every change outside the producer's scope, every edited function the delta map calls IDENTICAL without a review entry, every Cataclysm change without a "CAT:" comment, every recreation-only line without its "HWI-FEATURE(<name>)" tag, every CAT-TODO not on one line with its owner first, every SIMULATION field that moved in any stream (a FAIL unless the producer proved it is not this port's, or, for mission02 and mines only, it is a stated CAT: port move within THE STREAM RULE with its exe function), every stream or dump move the producer did not state, every generated file that a rerun of its generator does not reproduce, every change that breaks the Windows cross build's sources (a new file missing from meson.build, a GL entry point linked directly) is a finding.
4. Re-check the producer's DONE WHEN claim (${p.done}) yourself on the plain harness (silent, through tools/m2_harness.sh only; prefix your labels m3r3a-${p.key}-), re-read ${ANSWERS} for anything the producer missed, and check that the user's check in the report names a launcher command, a mission and moment and a setting or key that exist.
Fix factual errors you prove directly (code or doc; mark doc fixes "[audit: ...]"), keep the build green, and count the fixes. Write ${REPO}/docs/audits/m3-r3-${p.key}.md: what you checked, each finding with evidence, precision = correct/(correct+wrong) over the sampled checks, fixes, the mission-stream content your final pair gave (hwo_compare against the baseline) and every other guard-rail stream and dump you reran with its hash (the next port's reference), and a last line "Verdict: PASS|PASS-WITH-FIXES|FAIL - <reason>".
Then CHECKPOINT this port (even on FAIL, so the next port starts from a recorded state): ${CKPT} "M3-R3 ${p.key}: <verdict word> (<one-line summary>)" (it refuses forbidden paths; on an index.lock, wait 30 s and retry). Return the commit hash in "commit".`
}

const AUDITED_SCHEMA = { type: 'object', properties: { ports: { type: 'array', items: { type: 'object', properties: {
  key: { type: 'string' }, verdict: { type: 'string' }, commit: { type: 'string' } }, required: ['key', 'verdict', 'commit'] } } },
  required: ['ports'] }

async function portChain() {
  const out = []
  const probe = await agent(`In ${REPO}, for each key in [${PORTS.map(p => p.key).join(', ')}]: if docs/audits/m3-r3-<key>.md exists and its last non-empty line starts with "Verdict:", report {key, verdict: the verdict word (PASS, PASS-WITH-FIXES or FAIL), commit: the short hash of the newest commit whose subject starts with "M3-R3 <key>:" (git log --format='%h %s' | grep), or "" if none}. Omit keys whose audit doc is missing or has no Verdict line. Read only; change nothing.`,
    { label: 'probe:audited', phase: 'Port', schema: AUDITED_SCHEMA, model: 'opus', effort: 'high' })
  const audited = {}
  for (const a of (probe && probe.ports) || []) if (a.verdict && a.commit) audited[a.key] = a
  let base = ROUND_BASE
  for (const p of PORTS) {
    if (audited[p.key]) {
      const prior = PRIOR[p.key] || { produced: { report: `${REPO}/docs/m3-r3-${p.key}.md` }, audit: { verdict: audited[p.key].verdict, commit: audited[p.key].commit } }
      out.push({ key: p.key, produced: prior.produced, audit: prior.audit })
      base = audited[p.key].commit
      log(`${p.key}: already audited (${audited[p.key].verdict}, ${audited[p.key].commit}); skipped`)
      continue
    }
    const r = PRODUCED[p.key] || await agent(portPrompt(p, base), { label: p.label, phase: 'Port', schema: PROD_SCHEMA, model: 'opus', effort: 'high' })
    if (PRODUCED[p.key]) log(`${p.key}: producer finished in an earlier run (WIP snapshot); auditing it`)
    const v = await agent(auditPrompt(p, r, base), { label: 'audit:' + p.key, phase: 'Port', schema: AUDIT_SCHEMA, model: 'opus', effort: 'high' })
    out.push({ key: p.key, produced: r, audit: v })
    if (v && v.commit) base = v.commit
    log(`${p.key}: done_when=${r && r.done_when_met} milestone=${r && r.harness_milestone} missions=${r && r.missions_passed ? r.missions_passed.join(',') : '-'} verdict=${v && v.verdict}`)
  }
  return out
}

phase('Port')
log(`M3-R3: 5 src/ ports in sequence (${PORTS.map(p => p.key).join(', ')}); producers 1, 2 and 5 presentation only, producers 3 and 4 may move a mission stream only as a stated CAT: port; the headless Mission01 stream stays IDENTICAL to 1ae66610c3f02410 in every field; round base ${ROUND_BASE}`)
const all = (await portChain()).filter(Boolean)  // skips ports whose audit doc already has a Verdict line

phase('Integrate')
